#include <iostream>
#include <vector>
using namespace std;

int calculate(int a, int b, int l, int r) {
    if ((r - l + 1) > 2 * (a + b))
        return (a <= b) ? a + 1 : (2 * a - b);

    int size = 3 * (a + b) + 1;
    vector<int> patternSequence(size, 0);
    int lastValue = 0;

    for (int i = 1; i <= a; i++) {
        patternSequence[i] = i;
        lastValue = i;
    }

    for (int i = a + 1; i <= a + b; i++) {
        patternSequence[i] = lastValue;
    }

    auto containsInRange = [&](const vector<int>& array, int value, int start, int end) {
        for (int i = start; i <= end; i++) {
            if (array[i] == value)
                return true;
        }
        return false;
    };

    for (int i = a + b + 1; i <= a + b + a; i++) {
        int count = 1;
        while (containsInRange(patternSequence, count, a + b - a + 1, i - 1))
            count++;
        patternSequence[i] = count;
        lastValue = patternSequence[i];
    }

    for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
        patternSequence[i] = lastValue;
    }

    for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
        patternSequence[i] = patternSequence[i - (a + b)];
    }

    vector<int> coverageMap(25, 0);
    int startIdx = l % (a + b);
    if (startIdx == 0) startIdx += a + b;
    int endIdx = r - l + startIdx;
    if (endIdx < startIdx) endIdx += a + b;

    for (int i = startIdx; i <= endIdx; i++) {
        coverageMap[patternSequence[i]] = 1;
    }

    int totalCoverage = 0;
    for (int i = 1; i <= 24; i++)
        totalCoverage += coverageMap[i];

    return totalCoverage;
}

int main() {
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    cout << calculate(a, b, l, r) << "\n";
    return 0;
}

